select id into v_0 from public.svenska_nodes where root='sprakrad' and parent_id is not distinct from null and slug='de-och-dem';
if v_0 is null then
  insert into public.svenska_nodes(root,parent_id,slug,title,kind,note,position,content,utkast) values ('sprakrad',null,'de-och-dem','De, dem eller dom?','doc','Ett enkelt test och dess begränsningar',0,'{"title":"De, dem eller dom?","subtitle":"Vem gör något — och vem gäller det?","period":"Nutida svenska","category":"Språkråd","sections":[],"intro":"Som pronomen används de normalt som subjekt och dem som objekt eller efter en preposition. Ett byte till vi och oss kan hjälpa dig att se skillnaden i enkla meningar.","blocks":[{"id":"de-rule","type":"columns","title":"Prova med vi och oss","leftTitle":"Vi → de","leftBody":"Vi läser boken. → De läser boken.\nDe är subjekt: de utför handlingen.","rightTitle":"Oss → dem","rightBody":"Boken handlar om oss. → Boken handlar om dem.\nHär står pronomenet efter en preposition."},{"id":"de-example","type":"example","label":"Ett exempel till","text":"De såg oss. Vi såg dem.","note":"Vem som ser och vem som blir sedd avgör pronomenformen."},{"id":"de-limit","type":"note","label":"Observera","title":"Testet löser inte allt","body":"De används också framför bestämda substantivfraser: de röda böckerna. Då handlar det inte om ett personligt pronomen. Konstruktioner med de/dem som kräver också ett eget resonemang."},{"id":"de-dom","type":"text","title":"Och dom?","body":"Språkrådet rekommenderar de och dem som neutrala former i standardskrift. Dom kan passa i exempelvis repliker och personligare texter. Valet behöver ta hänsyn till textens ton och läsare."}],"sources":[{"title":"Språkrådet: När skriver man de och när skriver man dem?","url":"https://frageladan.isof.se/faqs/25461"},{"title":"Språkrådet: När används dom och när används de/dem?","url":"https://frageladan.isof.se/faqs/30753"}]}'::jsonb,false) returning id into v_0;
