select id into v_2 from public.svenska_nodes where root='grammatik' and parent_id is not distinct from null and slug='konjunktiv';
if v_2 is null then
  insert into public.svenska_nodes(root,parent_id,slug,title,kind,note,position,content,utkast) values ('grammatik',null,'konjunktiv','Om jag finge välja','doc','Vore, finge och andra konjunktivformer',0,'{"title":"Om jag finge välja","subtitle":"Konjunktivens möjligheter","period":"Nutida och äldre svenska","category":"Verb och modus","sections":[],"intro":"Konjunktiv kan uttrycka något tänkt, osäkert eller önskat. Vore lever kvar i dagens svenska; finge och flera andra former ger ofta texten en äldre eller litterär ton.","blocks":[{"id":"kon-example","type":"example","label":"Tänk om","text":"Om jag finge välja, vore svaret enkelt.","note":"Ett eget språkexempel: finge motsvarar här fick och vore motsvarar skulle vara."},{"id":"kon-table","type":"table","title":"Former att känna igen","columns":["Verb","Konjunktiv","Möjlig omskrivning"],"rows":[["vara","vore","skulle vara"],["få","finge","fick / skulle få"],["gå","ginge","gick / skulle gå"]]},{"id":"kon-style","type":"text","title":"Välj form efter textens ton","body":"Det vore trevligt är ett naturligt sätt att uttrycka en tänkt möjlighet. Finge är betydligt ovanligare. En omskrivning kan vara lättare att förstå, medan den äldre formen kan vara ett medvetet stilval."},{"id":"kon-leve","type":"note","label":"En släkting","title":"Leve och vare","body":"Former som leve och vare uttrycker önskan eller förhoppning. De kallas optativ eller presens konjunktiv, som i Leve sommaren!"}],"sources":[{"title":"Språkrådet: Vad kallas former som vore och finge?","url":"https://frageladan.isof.se/faqs/24717"}]}'::jsonb,false) returning id into v_2;
  insert into public.svenska_drafts(node_id,content,dirty) values (v_2,'{"title":"Om jag finge välja","subtitle":"Konjunktivens möjligheter","period":"Nutida och äldre svenska","category":"Verb och modus","sections":[],"intro":"Konjunktiv kan uttrycka något tänkt, osäkert eller önskat. Vore lever kvar i dagens svenska; finge och flera andra former ger ofta texten en äldre eller litterär ton.","blocks":[{"id":"kon-example","type":"example","label":"Tänk om","text":"Om jag finge välja, vore svaret enkelt.","note":"Ett eget språkexempel: finge motsvarar här fick och vore motsvarar skulle vara."},{"id":"kon-table","type":"table","title":"Former att känna igen","columns":["Verb","Konjunktiv","Möjlig omskrivning"],"rows":[["vara","vore","skulle vara"],["få","finge","fick / skulle få"],["gå","ginge","gick / skulle gå"]]},{"id":"kon-style","type":"text","title":"Välj form efter textens ton","body":"Det vore trevligt är ett naturligt sätt att uttrycka en tänkt möjlighet. Finge är betydligt ovanligare. En omskrivning kan vara lättare att förstå, medan den äldre formen kan vara ett medvetet stilval."},{"id":"kon-leve","type":"note","label":"En släkting","title":"Leve och vare","body":"Former som leve och vare uttrycker önskan eller förhoppning. De kallas optativ eller presens konjunktiv, som i Leve sommaren!"}],"sources":[{"title":"Språkrådet: Vad kallas former som vore och finge?","url":"https://frageladan.isof.se/faqs/24717"}]}'::jsonb,false);
